    clientToViewport(clientX,clientY){if(!Number.isFinite(clientX)||!Number.isFinite(clientY)||!C)return null;const r=C.getBoundingClientRect();if(!r.width||!r.height)return null;return{x:(clientX-r.left)*VIEW.w/r.width,y:(clientY-r.top)*VIEW.h/r.height,rect:r}},
    viewportToClient(x,y){if(!C)return null;const r=C.getBoundingClientRect();if(!r.width||!r.height)return null;return{x:r.left+x*r.width/VIEW.w,y:r.top+y*r.height/VIEW.h,rect:r}},
    worldToClient(x,y,camera=CameraProjection12.current()){const p=CameraProjection12.worldToViewport(x,y,camera);return CameraProjection12.viewportToClient(p.x,p.y)},
    tileCenterToClient(x,y,camera=CameraProjection12.current()){const p=CameraProjection12.tileCenter(x,y,camera);return CameraProjection12.viewportToClient(p.x,p.y)},
    clientToWorld(clientX,clientY,camera=CameraProjection12.current()){const p=CameraProjection12.clientToViewport(clientX,clientY);return p?{...CameraProjection12.viewportToWorld(p.x,p.y,camera),rect:p.rect}:null}
