   for(const [bx,by]of[[3,3],[w-7,3],[3,h-4],[w-7,h-4]]){put(bx,by,TT.RUMOR_ARCHIVE_PILE);put(bx+1,by,TT.RUMOR_ARCHIVE_PILE);put(bx+2,by,TT.RACK);}
