  const all=[...cells.values()],fresh=all.filter(c=>!occupied(c.x,c.y));if(fresh.length<24||all.some(c=>!inside(c.x,c.y)||nodes.some(n=>n.special&&Math.max(Math.abs(n.cx-c.x),Math.abs(n.cy-c.y))<7)))continue;
