function citadelDirection105(tower,level){
 const center=CITADEL_TOWERS105[12],dx=Math.round((tower.x-center.x)/48),dy=Math.round((tower.y-center.y)/48),parts=[];
 if(dx)parts.push((Math.abs(dx)>1?'극':'')+(dx<0?'서':'동')+(Math.abs(dx)>1?'':'쪽'));
 if(dy)parts.push((Math.abs(dy)>1?'극':'')+(dy<0?'북':'남')+(Math.abs(dy)>1?'':'쪽'));
 return `${parts.join(' ')||'중앙'} ${level}층`;
}
function citadelBridgeGuide105(release){
 const tower=CITADEL_TOWERS105[release.tower],room=release.theme?CITADEL_ROOM_THEMES105[release.theme].name:null;
 return {name:release.label+' 안내서',type:'guide',branchGuide105:true,bridgeGate105:release.key,identified:true,count:1,
  desc:`${release.label}의 철창을 해제하는 스위치는 ${citadelDirection105(tower,release.level)}에 있다. ${tower.name}${room?'의 '+room:'의 중앙 계단 옆'}에서 스위치를 누르면 ${release.targetLevel}층의 이 다리가 영구히 열린다.`,
  guideHint105:'방향은 흑성채 중앙탑을 기준으로 한다. 한 칸은 동쪽·서쪽·북쪽·남쪽, 두 칸은 극동·극서·극북·극남으로 표시한다.'};
}
